; search.asm -- chapter 11: a byte in a list: a loop with two ways out
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "search.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
where   EQU RAM_START          ; 4 addresses: where HL stopped
found   EQU RAM_START + 8      ; 4 bytes: 1 found, 0 not
; A list of 32 bytes searched for four values: the first, the eleventh,
; the last, and one that is not there. For each, whether it was found, where
; HL stopped, and, for the debugger, the time.
init:   di
        ld sp, SYS_AREA
        ld a, $11
        ld hl, list
        ld b, 32
s0:     call find
        ld (where + 0), hl      ; where it stopped
        ld a, 0
        jr nz, m0               ; not found: 0
        inc a                   ; found: 1
m0:     ld (found + 0), a
        ld a, $A7
        ld hl, list
        ld b, 32
s1:     call find
        ld (where + 2), hl      ; where it stopped
        ld a, 0
        jr nz, m1               ; not found: 0
        inc a                   ; found: 1
m1:     ld (found + 1), a
        ld a, $E2
        ld hl, list
        ld b, 32
s2:     call find
        ld (where + 4), hl      ; where it stopped
        ld a, 0
        jr nz, m2               ; not found: 0
        inc a                   ; found: 1
m2:     ld (found + 2), a
        ld a, $07
        ld hl, list
        ld b, 32
s3:     call find
        ld (where + 6), hl      ; where it stopped
        ld a, 0
        jr nz, m3               ; not found: 0
        inc a                   ; found: 1
m3:     ld (found + 3), a
stop:   jr stop

; find: the first of the B bytes from HL that equals A. Found: Z set, HL
;       on it. Not found: Z clear, since the last CP said not equal.
find:   cp (hl)
        ret z                   ; the way out when it is found
        inc hl
        djnz find               ; the way out when the list ends
        ret

list:   db $11, $20, $2F, $3E, $4D, $5C, $6B, $7A, $89, $98, $A7, $B6, $C5, $D4, $E3, $F2, $01, $10, $1F, $2E, $3D, $4C, $5B, $6A, $79, $88, $97, $A6, $B5, $C4, $D3, $E2
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
